== PresenceClient ==
import Foundation

/// The two daemon-side behaviours that make a robot feel present rather than parked.
///
/// A protocol of its own rather than four more methods on ``RobotAPIClient``, for
/// the reason ``CacheMaintenanceClient`` is one: conforming *is* the capability, so
/// a session over the Hugging Face relay — whose control channel carries none of
/// this — reports it unavailable instead of failing a switch somebody just moved.
///
/// **Neither can be read back.** No route reports whether either is on:
/// `media/status` describes the media server, and a face target's `detected: false`
/// cannot tell "tracking off" from "nobody in front of the camera". Whatever calls
/// this owns the state it asked for, and owes the reader an honest account of that.
public protocol PresenceClient: Sendable {
    /// Audio-reactive head wobbling, driven by audio the **daemon** is playing.
    ///
    /// A 200 does not mean it took: the route's call sits inside a media-server nil
    /// check that its `{"status": "ok"}` is outside of.
    func setWobbling(_ enabled: Bool) async throws

    /// Daemon-side visual face tracking.
    ///
    /// - Returns: whether the robot is now tracking. This answer *is* real — a robot
    ///   with no camera answers `enabled: false` under a 200.
    @discardableResult
    func setFaceTracking(_ enabled: Bool, weight: Double) async throws -> Bool
}

extension RobotConnection: PresenceClient {}

public extension RobotSession {
    /// False over the relay, whose data channel carries no media routes.
    var canControlPresence: Bool {
        client is any PresenceClient
    }

    func setWobbling(_ enabled: Bool) async throws {
        try await withPresenceClient { try await $0.setWobbling(enabled) }
    }

    /// - Parameter weight: how much of the tracked aim reaches the head, 0…1. The
    ///   daemon composes it as `linear_pose_interpolation(pose, aim, weight)`, so 1
    ///   replaces the pose outright and anything less leaves part of what the head was
    ///   already doing. Defaulted, so every existing caller means "all of it".
    /// - Returns: whether the robot took it. False from a camera-less robot, which
    ///   the screen reports rather than leaving a switch on over a robot watching
    ///   nothing.
    @discardableResult
    func setFaceTracking(_ enabled: Bool, weight: Double = 1) async throws -> Bool {
        try await withPresenceClient { try await $0.setFaceTracking(enabled, weight: weight) }
    }
}

extension RobotSession {
    func withPresenceClient<T>(_ call: (any PresenceClient) async throws -> T) async throws -> T {
        guard let client else { throw ReachyKitError.notConnected }
        guard let presence = client as? any PresenceClient else {
            throw ReachyKitError.wirelessFeaturesUnavailable
        }
        return try await call(presence)
    }
}
== presence model ==
import Foundation
import Observation
import ReachyKit

/// Drives the robot's two daemon-side presence behaviours from the viewport.
///
/// **This model is the only record of what is on, and it is a record of requests
/// rather than of the robot.** No route reports either state (see ``PresenceClient``),
/// so a switch here means "this is what this app last asked for". An app running on
/// the robot can change both underneath — `enable_wobbling` is an SDK call apps make
/// for themselves — and nothing can detect that. The screen says so in words rather
/// than implying a reading it does not have.
@MainActor
@Observable
final class PresenceModel {
    typealias SetWobbling = @MainActor (RobotSession, Bool) async throws -> Void
    typealias SetFaceTracking = @MainActor (RobotSession, Bool, Double) async throws -> Bool

    /// How much of the tracked aim reaches the head. **The floor is not zero, and that
    /// is the one decision in this file that the daemon does not make for us.**
    /// `enable_head_tracking(weight: 0)` is a real state — it pauses the worker and
    /// clears the aim without stopping the detector — but it is indistinguishable on
    /// screen from the switch above being off, and a switch that says "on" over a robot
    /// that visibly follows nothing is the kind of thing that gets reported as broken.
    /// So stopping is what the switch is for, and this only decides how far.
    ///
    /// The floor's value is a feel constant, like every number in the teleop path: it is
    /// low enough to read as "barely follows" and high enough to be visible on a robot.
    /// Only the robot settles it.
    static let weightRange: ClosedRange<Double> = 0.2 ... 1

    private(set) var isWobbling = false
    private(set) var isTracking = false
    private(set) var busy = false
    private(set) var lastError: String?

    /// Bound to the slider, so it moves under the thumb; **not** `private(set)` for that
    /// reason, and not what the robot has been told either — ``commitTrackingWeight``
    /// is. The split is `AudioSettingsModel`'s: a value the robot only hears about once
    /// the gesture ends.
    var trackingWeight: Double = 1

    /// The weight the robot was last sent, so a gesture that ends where it started sends
    /// nothing. Tracking's route is idempotent, unlike `volume/set` with its test beep,
    /// so this is thrift rather than a rule.
    private var appliedWeight: Double = 1

    private var standingDown = false
    private let setWobblingCall: SetWobbling
    private let setFaceTrackingCall: SetFaceTracking

